signatures.Experiments.AbstractLoopsJoint.reachable:
@Experiments.AbstractLoopsJoint.reachable_certifies_iff_kernel_subset : ∀ {World Trace Answer : Type}
  (answer : World → Answer) (trace : World → Trace),
  Experiments.AbstractLoopsJoint.Certifies answer trace ↔
    ∀ (first second : World), Experiments.AbstractLoopsJoint.kernel trace first second → answer first = answer second

signatures.Experiments.AbstractLoopsJoint.common_co:
@Experiments.AbstractLoopsJoint.common_collision_blocks_joint_certification : ∀ {World Left Right Answer : Type}
  (left : World → Left) (right : World → Right) (answer : World → Answer) (first second : World),
  left first = left second →
    right first = right second →
      answer first ≠ answer second →
        ¬Experiments.AbstractLoopsJoint.Certifies answer (Experiments.AbstractLoopsJoint.jointTrace left right)
